python
def duplicateCarriageProofStrip(readings):
    a=readings
    out=[]
    write=0
    for read in range(len(a)):
        if write==0 or a[read]!=a[write-1]:
            a[write]=a[read]
            write+=1
    out=a[:write]
    return out


java
class Solution {
  public int[] duplicateCarriageProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int write=0;for(int read=0;read<a.length;read++)if(write==0||a[read]!=a[write-1])a[write++]=a[read];for(int i=0;i<write;i++)out.add(a[i]);}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
